local ByteTable = {}
local Index = 1

-- Parse numerical array strings manually inside the VM
for num in string.gmatch(ExecutionBlock, "%S+") do
    ByteTable[Index] = tonumber(num)
    Index = Index + 1
end

pcall(function()
    
