local ExecutableSource = table.concat(OutputBytes)
local LoadRunner, LoadError = loadstring(ExecutableSource)

if LoadRunner then
    local success, runError = pcall(LoadRunner)
    if not success then
        warn("Execution error: " .. tostring(runError))
    end
else
    error("Security validation failed: " .. tostring(LoadError))
end
